export type DocPage={id:string;group:string;title:string;en:string;description:string;keywords?:string[];code?:string;demo?:()=>React.ReactNode;assets?:{filename:string;code:string;language?:'css'|'tsx'|'typescript'}[];props?:string[][];notes?:string[]; source?:string; localOnly?:boolean};
export const matchesSearch=(page:DocPage,query:string)=>`${page.title} ${page.en} ${page.description} ${page.keywords?.join(' ')||''}`.toLowerCase().includes(query.trim().toLowerCase());
function SearchDemo(){const input=useRef<SearchFieldRef>(null);const [value,setValue]=useState(''),[submitted,setSubmitted]=useState('');return <><Space wrap><SearchField ref={input} aria-label="搜索项目" placeholder="输入后按 Enter" value={value} onChange={setValue} onSearch={setSubmitted}/><RowActionButton onClick={()=>input.current?.focus()}>聚焦搜索框</RowActionButton></Space><p className="docs-muted" role="status">当前输入：{value||'空'} · 已提交：{submitted||'空'}</p></>}
function StatusDemo(){return <div style={{display:'grid',gap:20,width:'100%'}}><div><p className="docs-muted">业务状态</p><Space wrap>{(['neutral','info','success','warning','error'] as const).map((tone,i)=><StatusTag key={tone} tone={tone} title={`原始状态：${tone}`}>{['未开始','进行中','已完成','待确认','失败'][i]}</StatusTag>)}<StatusTag tone="warning" title="external_pending" style={{marginInlineEnd:0}}>未知状态（悬停查看原始值）</StatusTag></Space></div><div><p className="docs-muted">分类信息</p><Space wrap><CategoryTag>v0.2.5</CategoryTag><CategoryTag>GET</CategoryTag><CategoryTag>项目空间</CategoryTag></Space></div></div>}

function FormDemo(){const [form]=Form.useForm();const [saved,setSaved]=useState('');return <Form form={form} layout="vertical" onFinish={values=>setSaved(values.query)}><Form.Item name="query" label="项目关键词" rules={[{required:true,message:'请输入项目关键词'}]}><SearchField placeholder="直接绑定 Form.Item" allowClear/></Form.Item><Space><Button htmlType="submit" type="primary">验证并提交</Button><RowActionButton onClick={()=>{form.resetFields();setSaved('')}}>重置表单</RowActionButton></Space><p role="status" className="docs-muted">表单提交：{saved||'尚未提交'}</p></Form>}
function CompatibilityDemo(){return <div className="docs-compatibility"><div><span>接入边界</span><h3>先确认版本，再验证交互</h3><p>下表只列当前已验证的组合；升级框架或服务端渲染时，需要在真实消费项目里重新验证。</p></div><div className="docs-compatibility-grid"><div><strong>React / React DOM</strong><b>18.3.1</b><small>已验证</small></div><div><strong>Ant Design</strong><b>5.22.5</b><small>已验证</small></div><div><strong>React 19 / AntD 6 / SSR</strong><b>待验证</b><small>不要据此推断兼容</small></div></div><Disclosure label="展开表单绑定回归样例"><FormDemo/></Disclosure></div>}
function ActionsDemo(){const [count,setCount]=useState(0);return <><Space wrap><Button type="primary" onClick={()=>setCount(count+1)}>新建项目</Button><RowActionButton onClick={()=>setCount(count+1)}>编辑</RowActionButton><RowActionButton motionIcon="delete" danger onClick={()=>setCount(count+1)}>删除样例</RowActionButton><RowActionButton disabled>无权限</RowActionButton></Space><p className="docs-muted" role="status">已操作 {count} 次，仅更新本地计数。</p></>}

function NavigationDemo(){const [open,setOpen]=useState(['projects']),[selected,setSelected]=useState('/projects'),[collapsed,setCollapsed]=useState(false);return <><Button motionIcon="sidebar" iconActive={!collapsed} onClick={()=>setCollapsed(!collapsed)}>切换折叠</Button><div className="docs-demo-gap" style={{width:collapsed?64:240}}><BeautifulNavigation collapsed={collapsed} items={[{key:'projects',label:'项目空间',icon:<MotionIcon name="folder" size={16}/>,children:[{key:'/projects',label:'全部项目'},{key:'/groups',label:'项目组'}]},{key:'/settings',label:'设置',icon:<MotionIcon name="settings" size={16}/>}]} selectedKeys={[selected]} openKeys={open} onOpenChange={setOpen} onClick={({key})=>setSelected(key)}/></div><p role="status" className="docs-muted">当前选择：{selected}（仅本地状态）</p></>}
function HeaderDemo(){const [count,setCount]=useState(0);return <PageHeader title="项目空间" headingLevel={3} headingId="demo-project-title" description={<span>数量为 0 时仍保留摘要；标题层级由页面结构决定。</span>} meta={count} actions={<RowActionButton onClick={()=>setCount(count+1)}>添加样例</RowActionButton>}/>}
function ContentDemo(){const [state,setState]=useState<'empty'|'loading'|'error'>('empty');return <div style={{display:'grid',gap:20,width:'100%'}}><ButtonGroup aria-label="内容状态演示" style={{justifySelf:'start'}}><RowActionButton aria-pressed={state==='empty'} onClick={()=>setState('empty')}>空状态</RowActionButton><RowActionButton aria-pressed={state==='loading'} onClick={()=>setState('loading')}>加载中</RowActionButton><RowActionButton aria-pressed={state==='error'} onClick={()=>setState('error')}>失败</RowActionButton></ButtonGroup><ContentState role={state==='error'?'alert':'status'} loading={state==='loading'} title={state==='error'?'读取失败':state==='loading'?'正在加载':'没有匹配结果'} description={state==='error'?'样例错误，重试只切换为加载状态。':'状态由调用方控制，不自动推断成功。'} action={state==='error'?<Button motionIcon="retry" onClick={()=>setState('loading')}>重试</Button>:undefined}/></div>}
function TokensDemo(){return <div className="docs-theme-demo"><ThemeSwitch/><div className="docs-palette">{(['light','dark'] as const).map(mode=><section key={mode}><h3>{mode==='light'?'浅色':'暗色'}</h3>{Object.entries(palettes[mode]).filter(([key])=>['canvas','surface','raised','text','muted','accent','line'].includes(key)).map(([name,value])=><div className="docs-swatch" key={name}><i style={{background:value}}/><code>--ui-{name}</code><span>{value}</span></div>)}</section>)}</div></div>}
